//! A CmpFrame template's MatchEnd and that of its components, checked
//! against the C library.
//!
//! `cmp_match_end_oracle/cases.rs` is generated by
//! `tools/oracle_fixtures/cmp_match_end_probe.c`. C's CmpFrame PartMatch
//! gives an unset component the template's MatchEnd only while matching
//! it, then lays the result out with each component's own MatchEnd
//! (cmpframe.c:6856, :6936).

#[path = "cmp_match_end_oracle/cases.rs"]
mod cases;

use starlink_ast::coords::PointSet;
use starlink_ast::frames::FrameSearch;
use starlink_ast::frames::{BasicFrameBuilder, CmpFrame, Frame, FrameRef};

/// Apply the probe's comma-separated MinAxes, MaxAxes, MatchEnd and PreserveAxes
/// settings.
fn apply(f: &mut dyn Frame, settings: &str) {
    for s in settings.split(',') {
        match s.split_once('=').unwrap() {
            ("MaxAxes", v) => f.set_max_axes(v.parse().unwrap()).unwrap(),
            ("MinAxes", v) => f.set_min_axes(v.parse().unwrap()).unwrap(),
            ("MatchEnd", v) => f.set_match_end(v == "1").unwrap(),
            ("PreserveAxes", v) => f.set_preserve_axes(v == "1").unwrap(),
            other => panic!("no Rust set-up for {other:?}"),
        }
    }
}

fn run(cmp_settings: &str, c1_settings: &str) -> Option<Vec<(String, f64)>> {
    let mut target = BasicFrameBuilder::new(4).build().unwrap();
    for (i, l) in ["A", "B", "C", "D"].iter().enumerate() {
        target.set_label(i + 1, l).unwrap();
    }
    let mut c1 = BasicFrameBuilder::new(1).build().unwrap();
    apply(&mut c1, c1_settings);
    let mut t = CmpFrame::new(
        Box::new(c1),
        Box::new(BasicFrameBuilder::new(1).build().unwrap()),
    );
    apply(&mut t, cmp_settings);
    let fs = target.find_frame_template(&t, "").unwrap()?;
    let result = fs.frame(FrameRef::Current).unwrap();
    let map = fs.mapping(FrameRef::Base, FrameRef::Current).unwrap();
    let out = map
        .transform(&PointSet::from_rows([[1.0, 2.0, 3.0, 4.0]]), true)
        .unwrap();
    Some(
        (1..=result.naxes())
            .map(|i| (result.label(i).unwrap(), out.point(0)[i - 1]))
            .collect(),
    )
}

#[test]
fn match_end_layout_matches_the_c_library() {
    let mut failures = Vec::new();
    for &(cmp_settings, c1_settings, want) in cases::CASES {
        let got = run(cmp_settings, c1_settings);
        let want = want.map(|w| {
            w.iter()
                .map(|&(l, v)| (l.to_string(), v))
                .collect::<Vec<_>>()
        });
        if got != want {
            failures.push(format!(
                "[{cmp_settings} | {c1_settings}]: got {got:?}, C gives {want:?}"
            ));
        }
    }
    assert!(failures.is_empty(), "{}", failures.join("\n"));
}
